// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport android.content.Contextimport android.hardware.Sensorimport android.hardware.SensorEventimport android.hardware.SensorEventListenerimport android.hardware.SensorManagerimport kotlin.math.sqrt/** * NOUS — Android Accelerometer Probe (Module 6 v4 — Step 6.7). * * Real Android implementation of [AccelerometerProbe] — uses * [SensorManager] + [Sensor.TYPE_ACCELEROMETER] to detect physical * device motion, per strategy v4 §"Critical Engineering Fix 2: Camera * Sensor Baseline Power Drain". * * ## Why this matters * * The [SensorDutyCyclingController] needs a low-power signal to wake the * camera sensor when the user picks up the device. The accelerometer * (~5 mA when polled at 1 Hz) is 40× cheaper than the camera sensor * (~205 mA continuous). * * ## How it works * *  - Registers a [SensorEventListener] on the accelerometer at the *    `SENSOR_DELAY_UI` rate (50 ms — fast enough for motion detection, *    slow enough to save power vs `SENSOR_DELAY_FASTEST`). *  - Tracks the last-sampled acceleration magnitude. When *    [detectMotion] is called, computes the delta between the current *    and previous sample magnitudes. If the delta exceeds `threshold` *    (m/s²), returns true and resets the baseline. *  - Automatically unregisters the listener when [close] is called *    (lifecycle-bound via [AutoCloseable]). * * ## Real Android APIs used * *  - [Context.getSystemService] → [SensorManager] *  - [SensorManager.getDefaultSensor] → [Sensor.TYPE_ACCELEROMETER] *  - [SensorManager.registerListener] / [unregisterListener] * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 2: Sensor Duty Cycling</a> */class AndroidAccelerometerProbe(    context: Context,) : AccelerometerProbe, AutoCloseable {    private val sensorManager = context.getSystemService(Context.SENSOR_SERVICE) as? SensorManager    private val accelerometer: Sensor? =        sensorManager?.getDefaultSensor(Sensor.TYPE_ACCELEROMETER)    @Volatile    private var lastMagnitude: Float = SensorManager.STANDARD_GRAVITY    @Volatile    private var currentMagnitude: Float = SensorManager.STANDARD_GRAVITY    @Volatile    private var registered: Boolean = false    private val listener = object : SensorEventListener {        override fun onSensorChanged(event: SensorEvent) {            if (event.sensor.type != Sensor.TYPE_ACCELEROMETER) return            val x = event.values[0]            val y = event.values[1]            val z = event.values[2]            // Magnitude of the acceleration vector (includes gravity ~9.81 m/s²).            currentMagnitude = sqrt(x * x + y * y + z * z)        }        override fun onAccuracyChanged(sensor: Sensor?, accuracy: Int) {            // No-op — accuracy changes don't affect motion detection.        }    }    /**     * Register the sensor listener if not already registered.     *     * Idempotent — safe to call repeatedly. Called automatically on     * first [detectMotion] if the listener isn't registered yet.     */    fun register() {        if (registered) return        val sm = sensorManager ?: run {            Timber.tag(TAG).w("SensorManager unavailable — motion detection disabled.")            return        }        val sensor = accelerometer ?: run {            Timber.tag(TAG).w("No accelerometer on this device — motion detection disabled.")            return        }        // SENSOR_DELAY_UI = ~50 ms (20 Hz). Sufficient for motion wake-up,        // far cheaper than SENSOR_DELAY_FASTEST (~2 ms = 500 Hz).        val ok = sm.registerListener(listener, sensor, SensorManager.SENSOR_DELAY_UI)        registered = ok        if (!ok) Timber.tag(TAG).w("Failed to register accelerometer listener.")    }    override fun detectMotion(threshold: Float): Boolean {        if (!registered) register()        val current = currentMagnitude        val delta = kotlin.math.abs(current - lastMagnitude)        // Update baseline so subsequent calls measure motion *since last check*.        lastMagnitude = current        return delta > threshold    }    override fun close() {        sensorManager?.unregisterListener(listener)        registered = false    }    private companion object {        private const val TAG = "AndroidAccelProbe"    }}